cards.solution:
interface Barang {
  nama: string;
  harga: number;
}
interface BarangDiskon extends Barang {
  persen: number;
}
const sepatu: BarangDiskon = { nama: "Sepatu", harga: 200000, persen: 25 };
console.log(sepatu.nama, sepatu.harga - (sepatu.harga * sepatu.persen) / 100);
